// Host baseline bridge: preserve the old append operation and the actual
// caller's existing Zeroizing output. It gains no reservation before copying.
impl ChunkedDecoder {
 pub fn decode(&mut self, input: &[u8]) -> Result<Zeroizing<Vec<u8>>, Error> {
  let mut output=Zeroizing::new(Vec::new());
  self.decode_into(input, &mut output)?;
  Ok(output)
 }
}
// Byte-operation adapter for the former service's private read_head loop.
// Its existing erasing owner remains; only live receive access is injected.
pub struct ResponseHeadBuffer { bytes: Zeroizing<Vec<u8>> }
impl ResponseHeadBuffer {
 pub fn new() -> Self { Self { bytes: Zeroizing::new(Vec::new()) } }
 pub fn push(&mut self, input: &[u8]) -> Result<Option<(ResponseHead,Zeroizing<Vec<u8>>)>,Error> {
  self.bytes.extend_from_slice(input);
  match ResponseHead::parse(&self.bytes) {
   Ok((head, offset)) => {
    let mut body=Zeroizing::new(Vec::with_capacity(self.bytes.len()-offset));
    body.extend_from_slice(&self.bytes[offset..]);
    Ok(Some((head,body)))
   }
   Err(Error::Incomplete)=>Ok(None),
   Err(e)=>Err(e),
  }
 }
}

